@startuml

class Hospital {
  + Name : string
}

class Department {
  + Name : string
}

class Staff {
  + Name : string
}

class Patient {
  + Name : string
}

class MedicalRecord {
  + RecordId : string
}

class Admission {
  + AdmissionDate : date
  + DischargeDate : date
}

class Shift {
  + ShiftType : string
}

Hospital "1" *-- "1..*" Department
Department "1" -- "1..*" Staff : has
Department "1" -- "0..*" Patient : has
Patient "1" -- "1" MedicalRecord : has
Patient "1" -- "0..*" Admission : undergoes
Department "0..1" -- "0..*" Admission : manages
EmergencyRoom "1" -- "0..*" Staff : employs
EmergencyRoom "1" -- "0..*" Shift : operates

class EmergencyRoom {
}

@enduml

